-- 노모어내로우룸 방문 통계. IP는 저장하지 않고 날짜별 해시만 남긴다(자로자로와 같은 방식).
CREATE TABLE IF NOT EXISTS st_views (day TEXT NOT NULL, path TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, path));
CREATE TABLE IF NOT EXISTS st_visitors (day TEXT NOT NULL, v TEXT NOT NULL, PRIMARY KEY (day, v));
CREATE TABLE IF NOT EXISTS st_hours (day TEXT NOT NULL, h INTEGER NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, h));
CREATE TABLE IF NOT EXISTS st_src (day TEXT NOT NULL, src TEXT NOT NULL, path TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, src, path));
CREATE TABLE IF NOT EXISTS st_kw (day TEXT NOT NULL, kw TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, kw));
CREATE TABLE IF NOT EXISTS st_refs (day TEXT NOT NULL, host TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, host));
CREATE TABLE IF NOT EXISTS st_dev (day TEXT NOT NULL, dev TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, dev));
-- 예약 링크(트립닷컴) 클릭. path = 클릭한 페이지, label = 호텔 이름.
CREATE TABLE IF NOT EXISTS st_clicks (day TEXT NOT NULL, path TEXT NOT NULL, label TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, path, label));
-- 관리자 키를 여러 번 틀린 IP 해시를 잠깐 잠근다.
CREATE TABLE IF NOT EXISTS st_lock (k TEXT PRIMARY KEY, fails INTEGER NOT NULL DEFAULT 0, until INTEGER NOT NULL DEFAULT 0);
